'use strict';
const stories = {
  bhaibahini: { title: 'BhaiBahini', label: 'MENTORSHIP PLATFORM', lede: 'Connecting a multi-role product through thoughtful, consistent user journeys.', tags: ['Role-based UX', 'Figma prototyping', 'Design handoff', 'Responsive UI'], context: 'A mentorship platform serving mentors, mentees and administrators. The work spans different roles and the supporting journeys that connect them.', contribution: ['Designed mentor and mentee journeys, including onboarding flows.', 'Worked on administration, feedback and trust-and-safety screens.', 'Prepared design handoffs and collaborated on responsive UI improvements.'], lens: 'Keeping each role’s next step understandable while maintaining a coherent interface across the platform.', scope: 'The CV documents UX design and collaboration on this project at XylonTech. Public usage figures and measured business outcomes have not been supplied.', link: null },
  timecard: { title: 'Timecard & enterprise apps', label: 'ENTERPRISE WORKFLOWS', lede: 'Making operational interfaces easier to navigate, review and use.', tags: ['Enterprise UX', 'Timesheets', 'Review workflows', 'Interface consistency'], context: 'Enterprise business applications involving timecards, timesheets and review workflows. Related private client work includes learning management, performance evaluation, invoicing and hotel management systems.', contribution: ['Contributed UX and interface work for timesheet and review workflows.', 'Partnered with frontend engineers and QA on usability and responsive fixes.', 'Supported consistent interface patterns across workflow-based applications.'], lens: 'Making dense, task-oriented interfaces legible, with a clear relationship between information, actions and review states.', scope: 'Client identities, production screens and business metrics are not presented. All names, hours and statuses in the visual are illustrative.', link: null },
  alpine: { title: 'Alpine Club of Himalaya', label: 'TRAVEL WEB EXPERIENCE', lede: 'Helping people find their way into a travel experience.', tags: ['UI/UX design', 'Travel', 'Content-driven journeys', 'Visual design'], context: 'A travel website experience for trekking and tour offerings, also featured in Bishal’s public portfolio.', contribution: ['Worked on travel-related user interfaces and visual design.', 'Supported website presentation for trekking and tour content.', 'Worked on content-driven user journeys as a UI/UX Designer from February 2019 to June 2022.'], lens: 'Balancing the inspiration of travel with clear navigation and a readable presentation of destinations and offerings.', scope: 'The visual is an editorial interpretation with original vector art. It is not a reproduction of the live website, and no conversion or booking results are claimed.', link: {href:'https://alpineclubofhimalaya.com/',text:'Visit Alpine Club of Himalaya'} },
  swift: { title: 'Swift Holidays', label: 'MOBILE UI CONCEPT', lede: 'A travel experience explored through mobile interface design.', tags: ['Mobile UI', 'Figma mockup', 'Travel concept'], context: 'Swift Holidays is documented in the CV as a mobile app UI concept and Figma mockup.', contribution: ['Created a mobile app UI concept.', 'Explored the interface through a Figma mockup.'], lens: 'A mobile canvas for exploring travel content and visual hierarchy. The portfolio illustration offers an editorial interpretation of that theme.', scope: 'This is concept work. A launched app, engineering implementation, user testing or measured outcomes are not claimed. The original Figma file was not available for this portfolio build.', link: null }
};
const nav = document.querySelector('#navigation');
const menu = document.querySelector('.menu-toggle');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
const dialog=document.querySelector('#project-dialog');
let lastProject;
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{
  const story=stories[button.dataset.project];lastProject=button;
  const art=button.querySelector('.project-visual').cloneNode(true);art.setAttribute('aria-hidden','true');art.querySelectorAll('[id]').forEach(n=>{const old=n.id;const next=old+'-dialog';art.querySelectorAll(`[fill="url(#${old})"]`).forEach(p=>p.setAttribute('fill',`url(#${next})`));n.id=next;});
  document.querySelector('#dialog-content').innerHTML=`<article class="story"><span class="eyebrow">${story.label}</span><h2 id="dialog-title">${story.title}</h2><p class="story-lede">${story.lede}</p><div class="story-tags">${story.tags.map(tag=>`<span>${tag}</span>`).join('')}</div><div class="story-art"></div><section class="story-section"><h3>The context</h3><p>${story.context}</p></section><section class="story-section"><h3>My contribution</h3><ul>${story.contribution.map(item=>`<li>${item}</li>`).join('')}</ul></section><section class="story-section"><h3>The design lens</h3><p>${story.lens}</p></section><div class="story-note">${story.scope}</div><div class="story-links">${story.link?`<a class="text-link" href="${story.link.href}" target="_blank" rel="noopener">${story.link.text} ↗</a>`:''}<a class="text-link" href="mailto:gurungbsal18@gmail.com?subject=${encodeURIComponent('Let’s talk about '+story.title)}">Discuss this project ↗</a></div></article>`;
  document.querySelector('.story-art').append(art);dialog.showModal();dialog.scrollTop=0;document.body.classList.add('no-scroll');document.querySelector('.close-dialog').focus();
}));
function closeStory(){dialog.close();}
document.querySelector('.close-dialog').addEventListener('click',closeStory);
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeStory();}});
dialog.addEventListener('close',()=>{document.body.classList.remove('no-scroll');lastProject?.focus({preventScroll:true});});
document.querySelector('.copy-email').addEventListener('click',async()=>{const status=document.querySelector('.copy-status');try{await navigator.clipboard.writeText('gurungbsal18@gmail.com');status.textContent='Email copied.';}catch{status.textContent='Copy: gurungbsal18@gmail.com';}setTimeout(()=>{status.textContent='';},6000);});
